import {randomUUID} from 'node:crypto';
import type {PoolClient} from 'pg';
import {learningScopedFixture,learningAcceptedOriginal} from './setup';
import {requireOwnedLearningDatabase} from '../../../scripts/learning-environment';
import {activateLearning} from '../../../scripts/learning-activate';
import {createKnowledgeCandidate,submitKnowledgeCandidate,decideKnowledgeCandidate,reviseKnowledgeCandidate} from '../../../lib/server/knowledge/service';
import {readLearningCandidate,reviewLearningCandidate} from '../../../lib/server/learning/reviews';
import {prepareLearningEvaluation} from '../../../lib/server/learning/evaluation';
import {learningEvaluationCatalogDigest} from '../../../lib/server/learning/evaluation-context';
/** Representative prior/revised practice. No case answers or grading rubric are
 * embedded in either practice. All publication/review paths are synthetic/local. */
export async function learningRepresentativeEvaluation(db:PoolClient,budgetUsd:string){
 requireOwnedLearningDatabase(process.env,true);const scope=await learningScopedFixture(db),{actors,workspaceId,customerId}=scope,lineage=await learningAcceptedOriginal(db,actors.member,actors.admin,customerId);
 const checklist={namesAndDomainsRemoved:true,repositoriesAndLinksRemoved:true,peopleAndCommercialDetailsRemoved:true,identifyingConfigurationAndOutcomesRemoved:true,countsAndCombinedInferenceReviewed:true};
 const baseline={title:'Review deployment timing records',productVersion:'Unknown',problem:'Delivery timing needs a repeatable review',prerequisites:'An observed deployment workflow and accessible timing records',solution:'Collect start and completion times and review their differences',reasoning:'Recorded timings support a discussion about delivery duration',applicability:'Deployment workflows with timing records',limitations:'Timing alone does not show what caused a change',validation:'Check the reviewed timings with the delivery owner'};
 const created=await createKnowledgeCandidate(db,actors.member,{idempotencyKey:randomUUID(),customerId,payload:baseline,lineage:[lineage]});await submitKnowledgeCandidate(db,actors.member,created.id,{idempotencyKey:randomUUID(),expectedRevision:created.revision,expectedDigest:created.digest});await decideKnowledgeCandidate(db,actors.admin,created.id,{idempotencyKey:randomUUID(),expectedRevision:created.revision,expectedDigest:created.digest,action:'publish',rightsAttested:true,sanitizationRationale:'Reviewed synthetic prior practice before activation',checklist});
 const payload={...baseline,title:'Prepare a reproducible delivery measurement review',prerequisites:'Verify the workflow and the current accepted records before measuring; missing evidence leaves applicability unresolved',solution:'Ask the delivery owner to predeclare the workload, measurement boundary, timezone and comparable windows. Retain each deployment start/completion record, calculate elapsed minutes per deployment, and keep missing or conflicting observations visible. Submit the exact complete population and calculation for independent review before using a comparison.',reasoning:'A predeclared scope, traceable current records and explicit missingness make the measurement review reproducible',applicability:'A deployment timing review when its workload, boundaries and original evidence are established; other workflows require their own evidenced applicability assessment',limitations:'Unestablished applicability is an unknown, not proof of incompatibility. A timing comparison does not establish causality or approve any customer fact, shared publication, delivery acceptance or certification.',validation:'An independent reviewer checks original record identity, current status, complete population, comparable windows, arithmetic and missingness; unresolved prerequisites or conflicting records remain limitations rather than selected favorable results'};
 const candidate=await reviseKnowledgeCandidate(db,actors.member,created.id,{idempotencyKey:randomUUID(),expectedRevision:created.revision,expectedDigest:created.digest,payload,lineage:[lineage]});await submitKnowledgeCandidate(db,actors.member,candidate.id,{idempotencyKey:randomUUID(),expectedRevision:candidate.revision,expectedDigest:candidate.digest});await activateLearning(process.env.TURAS_ENVIRONMENT_ID!,workspaceId,true,requireOwnedLearningDatabase(process.env,true));
 const view=await readLearningCandidate(actors.admin,candidate.id),review=await reviewLearningCandidate(actors.admin,candidate.id,{contractVersion:'learning-v1',requestId:randomUUID(),expectedVersion:candidate.revision,revisionId:view.revisionId,contentDigest:view.digest,closureDigest:view.closureDigest,decision:'accept',rightsAttested:true,checklist,rationale:'Synthetic reviewed measurement improvement and independent original rights'});
 const evaluation=await prepareLearningEvaluation(actors.admin,{contractVersion:'learning-v1',requestId:randomUUID(),expectedVersion:candidate.revision,reviewId:review.targetId,baselineGeneration:1,catalogDigest:learningEvaluationCatalogDigest(),budgetUsd});if(!evaluation.targetId)throw Error('Representative evaluation identity required');return {...scope,candidate,evaluationId:evaluation.targetId};
}
